    public async getInvoiceFile(ctx: Context, invoiceExportRow: InvoiceExportRow): Promise<ExportedInvoiceFile> {
        logger.debug(ctx, "exportInvoice", {
            userInvoiceExportRow: invoiceExportRow
        });
        if (invoiceExportRow.state !== InvoiceExportState.SENT || !invoiceExportRow.invoice_no) {
            throw BoltError.code(ResponseCodes.INVOICE_EXPORT_ROW_IS_NOT_EXPORTED_YET);
        }

        const base64QRCode = await qrCode.toDataURL(invoiceExportRow.qr_code, {errorCorrectionLevel: "L"});
        if (!base64QRCode) {
            throw BoltError.errorWithData(ResponseCodes.INVOICE_EXPORT_ADEOPOS_PDF_SUCCESS, {
                invoice_no: invoiceExportRow.invoice_no,
                fiscal_code: invoiceExportRow.fiscal_code,
                token_code: invoiceExportRow.token_code,
                text: "success"
            });
        }

        throw BoltError.errorWithData(ResponseCodes.INVOICE_EXPORT_ADEOPOS_PDF_SUCCESS, {
            invoice_no: invoiceExportRow.invoice_no,
            fiscal_code: invoiceExportRow.fiscal_code,
            token_code: invoiceExportRow.token_code,
            qr_code: base64QRCode,
            text: "success"
        });
    } {noformat}

