We seem to be missing a check for instant parallel flow on {{generateAutomaticCommands}} function, which is called for auto-accept orders. Tried this fix locally and order behaved as expected for auto-accept regular instant flow: 

{noformat}export const generateAutomaticCommands = (
  order: DeliveryProviderAppService.ExtendedOrderDetails,
  mappingContext: OrderInfoMappingContext,
): AutomaticOrderCommand[] | undefined => {
  const orderState = order.provider_state_for_app;
  const { order_flow_settings: orderFlowSettings } = mappingContext.config;
  const {
    is_non_instant_parallel_enabled_for_order: isNonInstantParallelEnabledForOrder,
    is_instant_parallel_enabled_for_order: isInstantParallelEnabledForOrder,
  } = mappingContext.flags;
  const orderFlowSetting =
    orderFlowSettings?.[orderState as keyof DeliveryProviderAppService.ProviderOrderFlowSettings];
  const isManualStateTransitionByAppAfterNotification =
    orderFlowSetting?.condition_type ===
    DeliveryProviderAppService.ManualStateTransitionConditionType.BY_APP_AFTER_NOTIFICATION;

  if (
    (isNonInstantParallelEnabledForOrder || isInstantParallelEnabledForOrder) &&
    isManualStateTransitionByAppAfterNotification
  ) {
    switch (orderState) {
      case DeliveryProviderAppService.ExtendedProviderOrderState.WAITING_CONFIRMATION:
        return [
          {
            type: OrderCommandType.DO_ACCEPT,
            sound: { type: SoundName.incomingOrderRing, priority: 0, max_duration: 6500 },
            payload: { order_id: order.order_id },
          },
        ];
      case DeliveryProviderAppService.ExtendedProviderOrderState.WAITING_PREPARING_CONFIRMATION:
        return [
          {
            type: OrderCommandType.DO_START_PREPARATION,
            sound: { type: SoundName.courierAlertBeep, priority: 0 },
            payload: { order_id: order.order_id },
          },
        ];
      default:
        return undefined;
    }
  }
  return undefined;
};

